// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }

    function testFuzz_property(address logAddr, bool doInitialize) public {
        if (logAddr == address(0)) logAddr = address(1);

        if (doInitialize) {
            c.Initialized();
        }

        bool ok;
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        if (doInitialize) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
